<script lang="ts">
  import { onMount } from 'svelte';
  import Button from '$lib/components/ui/button/button.svelte';
  import { tr } from '../preferences.svelte';
  import { post,message,type Request } from './types';
  let {request,active=true}:{request:Request;active?:boolean}=$props();
  let data=$state<any>(null),busy=$state(false),failure=$state(''),notice=$state(''),hosts=$state(''),deviceName=$state('');
  let exported=$state<any>(null),confirmation=$state<any>(null),timer:ReturnType<typeof setTimeout>;
  const date=(value:string)=>value?new Date(value).toLocaleString():tr('Non disponible','Unavailable');
  function clearExport(){exported=null;clearTimeout(timer);}
  $effect(()=>{if(!active)clearExport();});
  async function load(){try{data=await request('/api/security/status');if(!hosts)hosts=(data.web?.suggestedHosts||data.server?.hosts||[]).join(', ');}catch(error){failure=message(error);}}
  async function action(input:any){if(busy||!data?.web?.csrfToken)return;busy=true;failure='';notice='';confirmation=null;try{
    const result=await post(request,'/api/security/actions',input,{'X-Bionic-CSRF':data.web.csrfToken});
    if(input.action==='issue-device'){clearExport();exported=result;timer=setTimeout(clearExport,Math.max(1,Date.parse(result.expiresAt)-Date.now()));await load();notice=tr('Certificat créé. Télécharge-le pendant sa durée de disponibilité.','Certificate created. Download it before it expires.');}
    else {data=result.status||result;notice=tr('État de sécurité actualisé.','Security state updated.');}
  }catch(error){failure=message(error);await load();notice=tr('État serveur relu. Aucune action n’a été renvoyée automatiquement.','Server state refreshed. No action was automatically submitted again.');}finally{busy=false;}}
  async function download(){if(!exported||busy)return;busy=true;failure='';try{const response=await fetch('/api/security/device-download',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Bionic-CSRF':data.web.csrfToken},body:JSON.stringify({exportId:exported.exportId})});if(!response.ok)throw Error((await response.json()).error);const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='bionic-appareil.p12';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exported={...exported,downloaded:true};notice=tr('Téléchargement demandé au navigateur.','Browser download requested.');}catch(error){failure=message(error);}finally{busy=false;}}
  onMount(()=>{void load();return clearExport;});
</script>

<h2>{tr('Connexion sécurisée','Secure connection')}</h2><p class="settings-description">{tr('Consulte et prépare HTTPS ou les certificats d’appareils. L’activation exige une vérification depuis le navigateur ; le code d’accès reste distinct.','Inspect and prepare HTTPS or device certificates. Activation requires a browser verification; the access code remains separate.')}</p>
<Button variant="outline" onclick={load} disabled={busy}>{tr('Actualiser la sécurité','Refresh security')}</Button>
{#if data}<dl class="settings-dl"><dt>{tr('Mode actif','Active mode')}</dt><dd>{data.mode==='mtls'?tr('HTTPS et certificat appareil','HTTPS and device certificate'):data.mode==='https'?'HTTPS':'HTTP'}</dd><dt>{tr('Adresses certifiées','Certified addresses')}</dt><dd>{data.server?.hosts?.join(', ')||tr('Aucun certificat serveur','No server certificate')}</dd><dt>{tr('Expiration serveur','Server expiry')}</dt><dd>{date(data.server?.expiresAt)}</dd><dt>{tr('Empreinte serveur','Server fingerprint')}</dt><dd>{data.server?.fingerprint||'—'}</dd><dt>{tr('Empreinte autorité','Authority fingerprint')}</dt><dd>{data.authority?.fingerprint||'—'}</dd></dl>
{#if data.authority}<a class="inline-link" href="/api/security/authority" download>{tr('Télécharger l’autorité publique','Download public authority certificate')}</a>{/if}
{#if data.web?.canConfigure}<h3>{tr('Préparer une connexion','Prepare a connection')}</h3><label class="setting-field">{tr('Adresses du PC à inclure','PC addresses to include')}<input bind:value={hosts} placeholder="192.168.1.100, localhost" disabled={busy} /></label>
<div class="settings-actions"><Button variant="outline" disabled={busy} onclick={()=>confirmation={action:'prepare',mode:data.mode==='mtls'?'mtls':'https',hosts:hosts.split(/[,\s]+/).filter(Boolean)}}>{data.mode==='http'?tr('Préparer HTTPS','Prepare HTTPS'):tr('Renouveler le serveur','Renew server certificate')}</Button>{#if data.mode==='https'&&data.devices?.some((device:any)=>!device.revokedAt&&Date.parse(device.expiresAt)>Date.now())}<Button variant="outline" disabled={busy} onclick={()=>confirmation={action:'prepare',mode:'mtls',hosts:hosts.split(/[,\s]+/).filter(Boolean)}}>{tr('Préparer les certificats obligatoires','Prepare required device certificates')}</Button>{/if}</div>
{#if data.candidate}<div class="settings-feedback"><p>{tr('Préparation en attente','Preparation pending')} · {data.candidate.mode} · {date(data.candidate.expiresAt)}</p>{#if data.web.proofPortProvisioned===false}<p>{tr('Le port de vérification doit être autorisé sur le PC avant de poursuivre.','The verification port must be authorized on the PC before continuing.')} {data.web.proofPort}</p>{/if}{#if data.web.proofRequest}<form action="/api/security/proof" method="post" target="_blank"><input type="hidden" name="proofId" value={data.web.proofRequest.id} /><input type="hidden" name="csrfToken" value={data.web.csrfToken} /><Button type="submit" variant="outline">{tr('Ouvrir la vérification HTTPS','Open HTTPS verification')}</Button></form>{:else}<p>{tr('Rouvre la préparation depuis le navigateur qui l’a créée.','Reopen the preparation from the browser that created it.')}</p>{/if}<Button variant="ghost" disabled={busy} onclick={()=>action({action:'cancel-preparation'})}>{tr('Annuler la préparation','Cancel preparation')}</Button></div>{/if}
{:else}<p class="settings-feedback">{tr('Cette instance expose les certificats en lecture seule.','This instance exposes certificates as read only.')}</p>{/if}
<h3>{tr('Appareils autorisés','Authorized devices')}</h3>
{#if !data.devices?.length}<p class="settings-description">{tr('Aucun certificat appareil.','No device certificate.')}</p>{/if}<ul class="settings-list">{#each data.devices||[] as device}<li><strong>{device.name}</strong><p>{device.revokedAt?tr('Révoqué','Revoked'):Date.parse(device.expiresAt)<Date.now()?tr('Expiré','Expired'):tr('Autorisé','Authorized')} · {date(device.expiresAt)}</p><details><summary>{tr('Empreinte','Fingerprint')}</summary><code>{device.fingerprint}</code></details>{#if data.web?.canIssueDevice&&!device.revokedAt}<div class="settings-actions"><Button variant="outline" disabled={busy} onclick={()=>confirmation={action:'issue-device',previousId:device.id}}>{tr('Renouveler','Renew')}</Button>{#if data.web.currentDeviceId!==device.id}<Button variant="ghost" disabled={busy} onclick={()=>confirmation={action:'revoke-device',id:device.id,confirmName:device.name}}>{tr('Révoquer cet appareil','Revoke device')}</Button>{:else}<span>{tr('Connexion actuelle','Current connection')}</span>{/if}</div>{/if}</li>{/each}</ul>
{#if data.web?.canIssueDevice}<form onsubmit={event=>{event.preventDefault();confirmation={action:'issue-device',name:deviceName.trim()};}}><label class="setting-field">{tr('Nom du nouvel appareil','New device name')}<input bind:value={deviceName} maxlength="80" required disabled={busy} /></label><Button type="submit" disabled={busy||!deviceName.trim()}>{tr('Créer un certificat appareil','Create device certificate')}</Button></form>{/if}
{#if exported}<div class="confirm-action"><h4>{tr('Certificat disponible temporairement','Certificate available temporarily')}</h4><p class="settings-description">{tr('Le mot de passe sert uniquement à importer ce fichier sur ton appareil. Il n’est pas conservé dans les préférences du navigateur.','This password is only used to import the file on your device. It is not saved in browser preferences.')}</p><label class="setting-field">{tr('Mot de passe du certificat','Certificate password')}<input readonly value={exported.passphrase} type="text" autocomplete="off" /></label><p>{tr('Expiration du téléchargement','Download expires')} : {date(exported.expiresAt)}</p><div class="settings-actions"><Button onclick={download} disabled={busy||exported.downloaded}>{tr('Télécharger le certificat .p12','Download .p12 certificate')}</Button><Button variant="ghost" onclick={clearExport}>{tr('Masquer ces informations','Hide this information')}</Button></div></div>{/if}
{/if}
{#if confirmation}<div class="confirm-action" role="group" aria-label={tr('Confirmer la modification de sécurité','Confirm security change')}><h3>{tr('Confirmer la modification','Confirm change')}</h3><p>{confirmation.action==='revoke-device'?tr('Retirer l’accès de cet appareil : ','Remove access for this device: ')+confirmation.confirmName:confirmation.action==='issue-device'?tr('Créer un certificat privé à importer sur l’appareil choisi.','Create a private certificate to import on the chosen device.'):tr('Préparer le nouveau certificat puis vérifier son accès avant activation.','Prepare the new certificate, then verify access before activation.')}</p><div class="settings-actions"><Button onclick={()=>action(confirmation)} disabled={busy}>{tr('Confirmer','Confirm')}</Button><Button variant="ghost" onclick={()=>confirmation=null}>{tr('Annuler','Cancel')}</Button></div></div>{/if}
{#if failure}<p class="settings-error" role="alert">{failure}</p>{/if}{#if notice}<p class="settings-feedback" role="status">{notice}</p>{/if}
